function insert(table:string,columns:string[],values:string[],id:string){return`insert into public.${table} (${columns.join(", ")})\nselect ${values.join(", ")}\nwhere not exists (select 1 from public.${table} where id=${uuid(id)});`;}
function guard(table:string,row:any,fields:[string,string][],label:string){return`if exists (select 1 from public.${table} where id=${uuid(row.id)} and not (${exact(fields)})) then raise exception 'H3-11D Cohort 2 deterministic-id conflict: ${label}'; end if;`;}

