  for(const x of r.canonicalPositive.evidence){const eq=x.target_table==="location_equipment"?uuid(x.targetId):"null",cap=x.target_table==="location_training_capabilities"?uuid(x.targetId):"null";out.push(insert("training_evidence",["id","training_source_id","location_training_capability_id","location_equipment_id","assertion","review_status","evidence_text","structured_evidence","observed_at","reviewed_at","content_hash"],[uuid(x.id),uuid(x.trainingSourceId),cap,eq,q(x.assertion),q(x.reviewStatus),q(x.evidenceText),json({factId:x.evidence_fact_id,relationshipKey:x.relationship_key,release:h}),ts(x.observedAt),ts(x.reviewedAt),q(x.contentHash)],x.id));}
